/**
 * [INPUT]: 依赖 Python zipfile 冻结的极小 ZIP 原字节，不依赖待测写入器
 * [OUTPUT]: 提供 full、patch、descriptor、badManifest 四份 Buffer 黄金夹具
 * [POS]: scripts 的 ZIP 门卫测试输入；固定 CRC、local/central 目录及 descriptor，供负控逐字节突变
 * [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
 */
const bytes = {
  full: 'UEsDBBQAAAAAAAAAIVwHGkXNDgAAAA4AAAARAAAAYnVuZGxlLmhhcm1vbnkuanNmaXh0dXJlIGJ1bmRsZVBLAQIUABQAAAAAAAAAIVwHGkXNDgAAAA4AAAARAAAAAAAAAAAAAACAAQAAAABidW5kbGUuaGFybW9ueS5qc1BLBQYAAAAAAQABAD8AAAA9AAAAAAA=',
  patch:
    '',
  descriptor:
    '',
  badManifest:
    '',
};
module.exports = Object.fromEntries(
  Object.entries(bytes).map(([name, value]) => [
    name,
    Buffer.from(value, 'base64'),
  ])
);
